mod stats {
  fn is_valid(n: Int) -> Bool {
    n >= 0
  }

  pub fn average(a: Int, b: Int) -> Int {
    (a + b) / 2
  }

  pub fn range(min: Int, max: Int) -> Int {
    if is_valid(min) && is_valid(max) && max >= min {
      return max - min;
    };
    0
  }
}

fn main() -> Int {
  use stats;
  let avg = stats.average(10, 20);
  let rng = stats.range(5, 25);
  io.println(avg);
  io.println(rng);
  return 0;
}
